#include <iostream>
using namespace std;

int passes = 0, fails = 0;

#define ASSERT_EQ(a, b) do { \
    if ((a) != (b)) { cout << "FAIL (line " << __LINE__ << ")\n"; fails++; } \
    else { cout << "PASS\n"; passes++; } \
} while(0)

#define ASSERT_TRUE(c) do { \
    if (!(c)) { cout << "FAIL (line " << __LINE__ << ")\n"; fails++; } \
    else { cout << "PASS\n"; passes++; } \
} while(0)

int add(int a, int b) { return a + b; }
int sub(int a, int b) { return a - b; }

int main() {
    ASSERT_EQ(add(2, 3), 5);
    ASSERT_EQ(sub(5, 3), 2);
    ASSERT_TRUE(5 > 3);
    cout << "\nPassed: " << passes << ", Failed: " << fails << endl;
    return 0;
}
